import { test, expect } from '@playwright/test';

test.describe('Modal Scroll Lock', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should prevent scrolling of the page behind the modal when modal is open', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal has a scrollable content area
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Verify page content is not scrollable
    const pageContent = page.locator('[data-testid="page-content"]');
    await expect(pageContent).toBeVisible();
    await expect(pageContent).not.toBeScrollable();

    // Verify modal content is scrollable
    await expect(modalContent).toBeScrollable();

    // Scroll to bottom of modal content
    await modalContent.evaluate((el) => el.scrollTop = el.scrollHeight);

    // Verify page content remains at top
    await expect(pageContent).toHaveScrollTop(0);

    // Close modal using getByRole
    const closeButton = page.getByRole('button', { name: /close modal/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify page content is scrollable again
    await expect(pageContent).toBeScrollable();
  });

  test('should restore page scrollability when modal is closed', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify page content is not scrollable
    const pageContent = page.locator('[data-testid="page-content"]');
    await expect(pageContent).toBeVisible();
    await expect(pageContent).not.toBeScrollable();

    // Scroll to bottom of modal content
    const modalContent = page.locator('[data-testid="modal-content"]');
    await modalContent.evaluate((el) => el.scrollTop = el.scrollHeight);

    // Close modal using getByRole
    const closeButton = page.getByRole('button', { name: /close modal/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify page content is scrollable again
    await expect(pageContent).toBeScrollable();
  });
});
